/* Bottom/sidebar tabs share one root entry. Detail pages keep their own Back steps. */
let routeDepth=0;
let pendingTab=null;
function appRoute(){return {gaku:true,navVersion:2,depth:routeDepth,page,category,kanaView,buku:typeof GakuBuku!=='undefined'?GakuBuku.getRoute():null,kaiwa:typeof GakuKaiwa!=='undefined'?GakuKaiwa.getRoute():null,kanji:typeof getKanjiRoute==='function'?getKanjiRoute():null,bunpo:typeof getBunpoRoute==='function'?getBunpoRoute():null,kotoba:typeof getKotobaRoute==='function'?getKotobaRoute():null,rangkuman:typeof getRangkumanRoute==='function'?getRangkumanRoute():null,quiz:typeof getQuizRoute==='function'?getQuizRoute():null,simulation:typeof GakuSimulation!=='undefined'?GakuSimulation.getRoute():null}}
function applyRoute(route){if(typeof GakuBuku!=='undefined')GakuBuku.restore(route.page==='Cerita'?route.buku:null);if(typeof GakuKaiwa!=='undefined')GakuKaiwa.restore(route.page==='Kaiwa'?route.kaiwa:null);if(typeof restoreQuizRoute==='function')restoreQuizRoute(route.quiz);if(typeof restoreRangkumanRoute==='function')restoreRangkumanRoute(route.rangkuman);if(typeof restoreKotobaRoute==='function')restoreKotobaRoute(route.kotoba);if(typeof restoreBunpoRoute==='function')restoreBunpoRoute(route.bunpo);if(typeof restoreKanjiRoute==='function')restoreKanjiRoute(route.kanji);page=route.page;category=KANA_GROUPS[route.category]?route.category:'Seion';kanaView=route.kanaView==='grid'?'grid':'groups';routeDepth=Number.isInteger(route.depth)&&route.depth>=0?route.depth:0;selectedKana=null;if(page==='Simulasi'&&typeof GakuSimulation!=='undefined'&&route.simulation)GakuSimulation.restore(route.simulation)}
function pushRoute(){routeDepth++;history.pushState(appRoute(),'')}
function showPage(name){if(name==='Cerita'&&page!==name&&typeof GakuBuku!=='undefined')GakuBuku.reset();if(name==='Kaiwa'&&page!==name&&typeof GakuKaiwa!=='undefined')GakuKaiwa.reset();if(typeof GakuSimulation!=='undefined'&&GakuSimulation.guard(()=>showPage(name)))return;if(page==='Simulasi'&&name!=='Simulasi'){switchTab(name);return}if(typeof quizGuard==='function'&&quizGuard(()=>showPage(name)))return;if(name==='Quiz'&&page!==name&&typeof resetQuizRoute==='function')resetQuizRoute();if(pendingTab!==null)return;if(name==='Simulasi'){openSimulation();return}if(name==='Beranda'){switchTab(name);return}stopAudio();if(name==='Rangkuman'&&page!==name&&typeof resetRangkumanRoute==='function')resetRangkumanRoute();if(name==='Kotoba'&&page!==name&&typeof resetKotobaRoute==='function')resetKotobaRoute();if(name==='Bunpo'&&page!==name&&typeof resetBunpoRoute==='function')resetBunpoRoute();if(name==='Kanji'&&page!==name&&typeof resetKanjiRoute==='function')resetKanjiRoute();const same=page===name&&kanaView==='groups';page=name;kanaView='groups';selectedKana=null;if(!same)pushRoute();updateScreen()}
function openSimulation(){stopAudio();closeModal();if(routeDepth>0){pendingTab='Simulasi';history.go(-routeDepth);return}page='Simulasi';kanaView='groups';selectedKana=null;pushRoute();if(typeof GakuSimulation!=='undefined')GakuSimulation.enter();else updateScreen()}
function switchTab(name){if(name==='Cerita'&&page!==name&&typeof GakuBuku!=='undefined')GakuBuku.reset();if(name==='Kaiwa'&&page!==name&&typeof GakuKaiwa!=='undefined')GakuKaiwa.reset();if(typeof GakuSimulation!=='undefined'&&GakuSimulation.guard(()=>switchTab(name)))return;if(name==='Simulasi'){showPage(name);return}if(name==='Quiz'&&page==='Quiz'&&typeof quizIsActive==='function'&&quizIsActive())return;if(typeof quizGuard==='function'&&quizGuard(()=>switchTab(name)))return;if(name==='Quiz'&&page!==name&&typeof resetQuizRoute==='function')resetQuizRoute();if(pendingTab!==null){pendingTab=name;return}stopAudio();closeModal();selectedKana=null;if(routeDepth>1){pendingTab=name;history.go(-routeDepth);return}if(name==='Beranda'&&routeDepth===1){history.back();return}page=name;kanaView='groups';if(routeDepth===0&&name!=='Beranda'){pushRoute()}else{history.replaceState(appRoute(),'')}updateScreen()}
function appBack(){if(document.querySelector('.modal')){closeModal();return}if(pendingTab!==null)return;if(typeof quizGuard==='function'&&quizGuard(()=>appBack()))return;if(routeDepth>0)history.back();else switchTab('Beranda')}
window.addEventListener('popstate',event=>{const route=event.state;if(pendingTab===null&&typeof GakuSimulation!=='undefined'&&GakuSimulation.handlePop(route))return;if(typeof quizHandlePop==='function'&&quizHandlePop(route))return;stopAudio();closeModal();if(!route?.gaku)return;applyRoute(route);if(pendingTab!==null){const target=pendingTab;pendingTab=null;if(target==='Simulasi'){openSimulation();return}page=target;kanaView='groups';if(target!=='Beranda')pushRoute()}updateScreen()});
function initAppNavigation(){const current=history.state;if(current?.gaku&&current.page==='Cerita'&&current.buku?.localDepth>0&&typeof GakuBuku!=='undefined'){page='Cerita';GakuBuku.reset();updateScreen();history.go(-Math.min(current.buku.localDepth,current.depth));return;}if(current?.learningPicker){history.back();return}if(current?.gaku&&current.navVersion===2){applyRoute(current)}else{const previous=current?.gaku?{...current}:null;page='Beranda';kanaView='groups';routeDepth=0;history.replaceState(appRoute(),'');if(previous&&previous.page!=='Beranda'){page=previous.page;category=KANA_GROUPS[previous.category]?previous.category:'Seion';pushRoute();if(previous.kanaView==='grid'&&['Hiragana','Katakana'].includes(page)){kanaView='grid';pushRoute()}}}updateScreen();if(window.location?.hash==='#simulasi'){history.replaceState(appRoute(),'',window.location.pathname+window.location.search);showPage('Simulasi')}}

window.addEventListener('pageshow',event=>{if(event.persisted){try{const saved=JSON.parse(localStorage.getItem('gaku-ui-history')||'[]');if(Array.isArray(saved))historyData=saved}catch{}updateScreen()}});
